def run_trie_ops(ops):
    root = {'children': {}, 'is_end': False}

    def insert(word):
        node = root
        for ch in word:
            if ch not in node['children']:
                node['children'][ch] = {'children': {}, 'is_end': False}
            node = node['children'][ch]
        node['is_end'] = True

    def find_node(s):
        node = root
        for ch in s:
            if ch not in node['children']:
                return None
            node = node['children'][ch]
        return node

    output = []
    for op, arg in ops:
        if op == 'insert':
            insert(arg)
        elif op == 'search':
            node = find_node(arg)
            output.append(node is not None and node['is_end'])
        elif op == 'startsWith':
            output.append(find_node(arg) is not None)
    return output

